const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const defaults={collections:['Personal','Work','Experiments'],overrides:{},custom:[],order:[],favorites:[],hidden:[],name:'dock',theme:'light',accent:'#517458',density:'comfortable',view:'grid'};
let state;try{state={...structuredClone(defaults),...JSON.parse(localStorage.getItem('dock-v1')||'{}')}}catch{state=structuredClone(defaults)}
let discovered=[],scope='All projects',filter='all',query='',sort='manual',dragId=null;
const colors={sage:'#e8eee3',peach:'#f7e7dd',lavender:'#ece8f4',blue:'#e5edf5',sand:'#f2eddf',rose:'#f4e4e6'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){localStorage.setItem('dock-v1',JSON.stringify(state));apply();render()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function apply(){document.body.classList.toggle('dark',state.theme==='dark');document.body.classList.toggle('compact',state.density==='compact');document.documentElement.style.setProperty('--accent',state.accent);$('#brandname').textContent=state.name;$('#projects').classList.toggle('list',state.view==='list');$('#grid-view').classList.toggle('active',state.view==='grid');$('#list-view').classList.toggle('active',state.view==='list')}
function projects(){return [...discovered,...state.custom].filter(p=>!state.hidden.includes(p.id)).map(p=>({...p,...state.overrides[p.id]}))}
function safeURL(v){try{const url=new URL(v,location.href);return ['http:','https:'].includes(url.protocol)?url.href:null}catch{return null}}
function openProject(id){const p=projects().find(p=>p.id===id);if(!p)return;const url=safeURL(p.url);if(url)location.href=url;else toast('Add a valid project URL in project settings.')}
const folder=`<svg viewBox="0 0 40 34" fill="none"><path d="M3 9a3 3 0 0 1 3-3h9l4 4h15a3 3 0 0 1 3 3v14a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3V9Z" fill="currentColor" opacity=".25"/><path d="M3 13h34v14a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3V13Z" fill="currentColor" opacity=".5"/></svg>`;
function art(p,i){if(p.icon==='orbit')return '<div class="art-orbit"></div><div class="art-orbit"></div><span class="art-symbol">✳</span>';if(p.icon==='type')return '<span class="art-symbol" style="color:#aa94bd">Aa</span>';if(p.icon==='code')return '<span class="art-symbol" style="font-size:43px;color:#89a2b6">&lt;/&gt;</span>';return `<div class="art-window"><div class="art-content"><div class="art-side"></div><div class="art-lines"><div class="art-line"></div><div class="art-line" style="width:50%"></div><div class="art-blocks"><span></span><span></span><span></span></div></div></div></div>${p.icon==='notes'?'<span class="art-title">Little ideas. Big things.</span>':''}`}
function render(){const all=projects();$('#total-stat').textContent=all.length;$('#active-stat').textContent=all.filter(p=>p.status==='In progress').length;$('#favorite-stat').textContent=all.filter(p=>state.favorites.includes(p.id)).length;$('#navigation').innerHTML=[['All projects','▦',all.length],['Favorites','☆',all.filter(p=>state.favorites.includes(p.id)).length],['Recently added','◷','']].map(([s,icon,count])=>`<button class="${scope===s?'active':''}" data-scope="${s}"><span>${icon}</span>${s}<span class="nav-count">${count}</span></button>`).join('');$('#collections').innerHTML=state.collections.map((c,i)=>`<button data-scope="${esc(c)}" class="${scope===c?'active':''}" data-drop="${esc(c)}"><span class="collection-dot" style="background:${['#a6b794','#d8af94','#b7a4ce','#91acc5'][i%4]}"></span>${esc(c)}<span class="nav-count">${all.filter(p=>p.collection===c).length}</span></button>`).join('');$('#collection-count').textContent=state.collections.length;$('#collection-cards').innerHTML=state.collections.map((c,i)=>`<button class="collection-card" data-scope="${esc(c)}" data-drop="${esc(c)}"><span class="folder-icon" style="color:${['#8ea773','#cf9c7a','#ad97c4','#91acc5'][i%4]}">${folder}</span><span><strong>${esc(c)}</strong><small>${all.filter(p=>p.collection===c).length} projects</small></span><span class="arrow">↗</span></button>`).join('');$('#crumb').textContent=scope;$('#page-title').innerHTML=esc(scope)+'<span class="heading-dot">.</span>';$('#subtitle').textContent=scope==='All projects'?'A home for everything you’re building.':scope==='Favorites'?'Your best ideas, close at hand.':scope==='Recently added'?'The newest additions to your workspace.':`A little space for your ${scope.toLowerCase()} projects.`;
let list=all.filter(p=>(scope==='All projects'||scope==='Recently added'||scope==='Favorites'&&state.favorites.includes(p.id)||p.collection===scope)&&(filter==='all'||p.status===filter)&&`${p.name} ${p.description} ${p.collection}`.toLowerCase().includes(query.toLowerCase()));
if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));else if(sort==='recent'||scope==='Recently added')list.sort((a,b)=>new Date(b.updated||0)-new Date(a.updated||0));else list.sort((a,b)=>(state.order.indexOf(a.id)<0?999:state.order.indexOf(a.id))-(state.order.indexOf(b.id)<0?999:state.order.indexOf(b.id)));
$('#project-count').textContent=all.length;$('#results-count').textContent=`${list.length} project${list.length===1?'':'s'}`;
$('#projects').innerHTML=list.map((p,i)=>`<article class="project-card" draggable="true" data-id="${esc(p.id)}"><div class="project-art" style="--card-color:${colors[p.color]||colors.sage}" data-open="${esc(p.id)}" role="link" tabindex="0" aria-label="Open ${esc(p.name)}">${art(p,i)}</div><button class="star ${state.favorites.includes(p.id)?'selected':''}" data-star="${esc(p.id)}" aria-label="${state.favorites.includes(p.id)?'Unfavorite':'Favorite'} ${esc(p.name)}">${state.favorites.includes(p.id)?'★':'☆'}</button><div class="project-info"><div class="project-title-row"><button class="project-name" data-open="${esc(p.id)}">${esc(p.name)}</button><button class="project-menu" data-edit="${esc(p.id)}" aria-label="Edit ${esc(p.name)}">···</button></div><p class="project-description">${esc(p.description)}</p><div class="project-meta"><span class="status ${p.status==='Planning'?'planning':p.status==='Complete'?'complete':''}">${esc(p.status||'In progress')}</span><small>${esc(p.collection||'Personal')}</small></div></div></article>`).join('')+(list.length===0?'<div class="empty">No projects here yet. Add a project or try another search.</div>':'')+`<button class="add-card" id="add-card"><span class="plus">+</span><strong>Room for your next idea</strong><small>Add a project to your workspace</small></button>`;
$$('[data-scope]').forEach(el=>el.onclick=()=>{scope=el.dataset.scope;render()});$$('[data-star]').forEach(el=>el.onclick=()=>{const id=el.dataset.star;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save()});$$('[data-open]').forEach(el=>{el.onclick=()=>openProject(el.dataset.open);el.onkeydown=e=>{if(e.key==='Enter')openProject(el.dataset.open)}});$$('[data-edit]').forEach(el=>el.onclick=()=>projectModal(el.dataset.edit));$('#add-card').onclick=()=>projectModal();
$$('.project-card').forEach(el=>{el.ondragstart=e=>{dragId=el.dataset.id;e.dataTransfer.setData('text/plain',dragId);el.classList.add('dragging')};el.ondragend=()=>{$$('.dragging,.drop-target').forEach(x=>x.classList.remove('dragging','drop-target'));dragId=null};el.ondragover=e=>{e.preventDefault();el.classList.add('drop-target')};el.ondragleave=()=>el.classList.remove('drop-target');el.ondrop=e=>{e.preventDefault();if(!dragId||dragId===el.dataset.id)return;const ids=list.map(p=>p.id).filter(x=>x!==dragId);ids.splice(ids.indexOf(el.dataset.id),0,dragId);state.order=[...ids,...all.map(p=>p.id).filter(x=>!ids.includes(x))];sort='manual';$('#sort').value=sort;save();toast('Project order saved')}});
$$('[data-drop]').forEach(el=>{el.ondragover=e=>{e.preventDefault();el.classList.add('drop-target')};el.ondragleave=()=>el.classList.remove('drop-target');el.ondrop=e=>{e.preventDefault();if(!dragId)return;state.overrides[dragId]={...state.overrides[dragId],collection:el.dataset.drop};save();toast(`Moved to ${el.dataset.drop}`)}})}
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button id="close-modal" aria-label="Close dialog">×</button></div>${body}`;$('#close-modal').onclick=()=>$('#modal').close();if(!$('#modal').open)$('#modal').showModal()}
function projectModal(id){const p=projects().find(p=>p.id===id)||{name:'',description:'',url:'',collection:state.collections.includes(scope)?scope:state.collections[0],status:'In progress',color:'sage'};modal(id?'Project settings':'Make room for an idea',`<p>${id?'Personalize this project or move it to another collection.':'Add a link to a project, or ask Codex to create a folder in projects/.'}</p><form id="project-form"><label>Project name<input name="name" required maxlength="80" placeholder="My next big thing" value="${esc(p.name)}"></label><label>Description<textarea name="description" maxlength="180" placeholder="What are you building?">${esc(p.description)}</textarea></label><label>Project URL or relative path<input name="url" required placeholder="projects/my-project/ or https://…" value="${esc(p.url)}"></label><div class="form-row"><label>Collection<select name="collection">${state.collections.map(c=>`<option ${c===p.collection?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Status<select name="status">${['In progress','Planning','Complete'].map(c=>`<option ${c===p.status?'selected':''}>${c}</option>`).join('')}</select></label></div><label>Cover color<select name="color">${Object.keys(colors).map(c=>`<option ${c===p.color?'selected':''}>${c}</option>`).join('')}</select></label><div class="modal-actions">${id?'<button type="button" class="secondary danger" id="remove-project">Remove from hub</button>':''}<button type="button" class="secondary" id="cancel">Cancel</button><button class="primary" type="submit">${id?'Save changes':'Add project'} ↗</button></div></form>`);$('#cancel').onclick=()=>$('#modal').close();$('#project-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(!safeURL(data.url)){toast('Use an http(s) URL or a relative project path.');return}if(id)state.overrides[id]={...state.overrides[id],...data};else state.custom.push({...data,id:crypto.randomUUID(),updated:new Date().toISOString()});save();$('#modal').close();toast(id?'Project updated':'Project link added')};if(id)$('#remove-project').onclick=()=>{state.hidden.push(id);save();$('#modal').close();toast('Removed from hub. Repository files are kept.')};}
function collectionModal(){modal('Your collections',`<p>Group projects in a way that makes sense to you. Drag any project into a collection to move it.</p><div id="collection-editor">${state.collections.map((c,i)=>`<div style="display:flex;gap:8px;align-items:center"><input aria-label="Collection name" id="collection-${i}" value="${esc(c)}" maxlength="40"><button class="secondary" data-rename="${i}">Save</button><button class="secondary" data-remove="${i}" aria-label="Remove ${esc(c)}">×</button></div>`).join('')}</div><form id="collection-form"><label>New collection<input name="name" required maxlength="40" placeholder="Something wonderful"></label><div class="modal-actions"><button class="primary">+ Create collection</button></div></form>`);$('#collection-form').onsubmit=e=>{e.preventDefault();const n=new FormData(e.target).get('name').trim();if(!n||state.collections.includes(n)||['All projects','Favorites','Recently added'].includes(n)){toast('Choose a unique collection name.');return}state.collections.push(n);save();collectionModal()};$$('[data-rename]').forEach(b=>b.onclick=()=>{const i=+b.dataset.rename,old=state.collections[i],n=$(`#collection-${i}`).value.trim();if(!n||['All projects','Favorites','Recently added'].includes(n)||state.collections.includes(n)&&n!==old){toast('Choose a unique collection name.');return}projects().filter(p=>p.collection===old).forEach(p=>state.overrides[p.id]={...state.overrides[p.id],collection:n});state.collections[i]=n;if(scope===old)scope=n;save();collectionModal()});$$('[data-remove]').forEach(b=>b.onclick=()=>{if(state.collections.length===1){toast('Keep at least one collection.');return}const old=state.collections.splice(+b.dataset.remove,1)[0];projects().filter(p=>p.collection===old).forEach(p=>state.overrides[p.id]={...state.overrides[p.id],collection:state.collections[0]});if(scope===old)scope='All projects';save();collectionModal()})}
function settings(){modal('Make yourself at home',`<p>A workspace that feels like yours. Settings are saved in this browser.</p><label>Workspace name<input id="setting-name" value="${esc(state.name)}" maxlength="24"></label><label>Accent color</label><div class="swatches">${['#517458','#6979a2','#9c6c58','#89729d','#337f80','#a77f3e'].map(c=>`<button class="swatch ${state.accent===c?'active':''}" data-color="${c}" style="background:${c}" aria-label="Accent ${c}"></button>`).join('')}</div><div class="form-row"><label>Appearance<select id="setting-theme"><option value="light" ${state.theme==='light'?'selected':''}>Light</option><option value="dark" ${state.theme==='dark'?'selected':''}>Dark</option></select></label><label>Card density<select id="setting-density"><option value="comfortable" ${state.density==='comfortable'?'selected':''}>Comfortable</option><option value="compact" ${state.density==='compact'?'selected':''}>Compact</option></select></label></div><div class="backup-row"><button class="secondary" id="export">Export settings ↓</button><button class="secondary" id="import">Import settings ↑</button><input id="import-file" type="file" accept="application/json" hidden style="display:none"></div>${state.hidden.length?'<button class="secondary" id="restore" style="margin-top:12px">Restore removed projects</button>':''}<div class="modal-actions"><button class="primary" id="settings-save">Save preferences</button></div>`);let accent=state.accent;$$('[data-color]').forEach(b=>b.onclick=()=>{accent=b.dataset.color;$$('[data-color]').forEach(x=>x.classList.toggle('active',x===b))});$('#settings-save').onclick=()=>{state.name=$('#setting-name').value.trim()||'dock';state.theme=$('#setting-theme').value;state.density=$('#setting-density').value;state.accent=accent;save();$('#modal').close();toast('A little more you. Preferences saved.')};$('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='dock-settings.json';a.click();URL.revokeObjectURL(a.href)};$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(!Array.isArray(data.collections)||!data.collections.length||!data.collections.every(x=>typeof x==='string')||!Array.isArray(data.custom)||!Array.isArray(data.favorites)||typeof data.overrides!=='object')throw Error();for(const key of ['hidden','order'])if(data[key]&&!Array.isArray(data[key]))throw Error();state={...structuredClone(defaults),...data};save();$('#modal').close();toast('Workspace settings imported')}catch{toast('That file is not a valid Dock settings backup.')}};if($('#restore'))$('#restore').onclick=()=>{state.hidden=[];save();settings();toast('Removed projects restored')}}
$('#settings').onclick=settings;$('#workspace').onclick=settings;$('#theme-toggle').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';save()};$('#new-project').onclick=()=>projectModal();['#add-collection','#new-collection','#manage-collections'].forEach(s=>$(s).onclick=collectionModal);$('#search').oninput=e=>{query=e.target.value;render()};$('#sort').onchange=e=>{sort=e.target.value;render()};$('#grid-view').onclick=()=>{state.view='grid';save()};$('#list-view').onclick=()=>{state.view='list';save()};$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});$('#how-it-works').onclick=()=>modal('Your repo. Automatically organized.',`<p>Create a folder under <code>projects/</code> in this repository. Dock discovers it automatically during development and on every GitHub Pages deployment.</p><p>Add an <code>index.html</code> to open the project directly. Add an optional <code>project.json</code> to customize its name, collection, description, or deployed URL. Other folders open in a file detail view.</p><p>Ask Codex: “Add a new project to my Dock hub.” The repository instructions explain where it belongs. Push the change and GitHub Actions rebuilds your hub.</p><p>Links and appearance changes made here are saved in your browser. Use Settings → Export to back them up.</p>`);document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();$('#search').focus()}});$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
async function refresh(){try{const response=await fetch('projects.json?t='+Date.now(),{cache:'no-store'});if(!response.ok)throw Error();const data=await response.json();if(JSON.stringify(data)!==JSON.stringify(discovered)){discovered=data;for(const p of data)if(p.collection&&!state.collections.includes(p.collection))state.collections.push(p.collection);render()}$('#discovery-label').textContent='Auto-discovery enabled'}catch{$('#discovery-label').textContent='Project discovery unavailable — retrying'}}apply();render();refresh();setInterval(refresh,15000);
